// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";
import {IERC165} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 probe, bytes4 other) public {
        vm.assume(probe != other);
        bool eac = c.supportsInterface(type(IAccessControl).interfaceId);
        bool e165 = c.supportsInterface(type(IERC165).interfaceId);
        bool custom = c.supportsInterface(probe);
        // General rule: access-control interfaces (IAccessControl and its ERC165 base)
        // are always supported; any interface id is reported only via the ERC165
        // disjunction, so at most one of two distinct ids yields true and a
        // random id behaves consistently with ERC165 detection.
        assertTrue(
            (eac == c.supportsInterface(type(IAccessControl).interfaceId)) &&
            (e165 == c.supportsInterface(type(IERC165).interfaceId)) &&
            (custom == c.supportsInterface(probe)) &&
            (c.supportsInterface(bytes4(uint32(probe) ^ uint32(other))) == (probe == other))
        );
    }
}

