pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 ERC165_ID;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        ERC165_ID = type(IERC165).interfaceId;
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // General rule: for any interfaceId, C supports the IERC165 interface itself
        // (and any interface it genuinely implements); in particular, for every input,
        // supportsInterface(IERC165.interfaceId) must be true regardless of the fuzzed id.
        // The mutant removes the super disjunct and returns false for the IERC165 id.
        assertTrue(c.supportsInterface(ERC165_ID) || !(interfaceId == ERC165_ID));
    }
}

