pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 accessId;
    bytes4 erc165Id;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        accessId = bytes4(keccak256("hasRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
            ^ bytes4(keccak256("grantRole(bytes32,address)"))
            ^ bytes4(keccak256("revokeRole(bytes32,address)"))
            ^ bytes4(keccak256("renounceRole(bytes32,address)"));
        erc165Id = bytes4(keccak256("supportsInterface(bytes4)"));
    }

    function testFuzz_property(uint256 rawId) public {
        bytes4 x = bytes4(uint32(rawId));
        bool reported = c.supportsInterface(x);
        bool expected = (x == accessId) || (x == erc165Id);
        assertTrue(reported == expected);
    }
}

