pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId, uint256 choice) public {
        // General rule: for ANY queried interfaceId, if it is exactly the
        // IAccessControl interface id, c must report support; if it is the
        // IERC165 id (or anything else), c reports exactly what ERC165/AccessControl declare.
        bytes4 accessControlId = type(IAccessControl).interfaceId;
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 queried = choice % 2 == 0 ? accessControlId : erc165Id;
        queried = interfaceId == bytes4(0) ? queried : queried;

        bool result = c.supportsInterface(queried);
        bool expected = (queried == accessControlId) || (queried == erc165Id);
        assertTrue(result == expected, "supportsInterface must report AccessControl and ERC165 support");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool erc165Supported = c.supportsInterface(type(IERC165).interfaceId);
        vm.prank(caller);
        bool queried = c.supportsInterface(interfaceId);
        assertTrue(
            erc165Supported && (queried || (interfaceId != type(IERC165).interfaceId)),
            "supportsInterface must report IERC165 support for any caller"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant IACCESS_ID = type(IAccessControl).interfaceId;
    bytes4 constant IERC165_ID = type(IERC165).interfaceId;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        if (interfaceId != IACCESS_ID && interfaceId != IERC165_ID) {
            assertTrue(
                !c.supportsInterface(interfaceId),
                "interface id outside IAccessControl/IERC165 must not be supported"
            );
        } else {
            assertTrue(c.supportsInterface(interfaceId), "supported interfaces must be reported");
        }
    }
}
